// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new MY_BANK(address(log_));
    }

    function testFuzz_property(uint256 _unlockTime, uint256 _deposit, uint256 _am, address _caller) public {
        // Keep the caller an actual EOA, not the test/contract itself or the C contract.
        vm.assume(_caller != address(0) && _caller != address(this) && _caller != address(c));
        // Make the deposit admissible for Put and for the Collect guard.
        uint256 deposit = bound(_deposit, c.MinSum(), 10 ether);
        uint256 unlockTime = bound(_unlockTime, 0, block.timestamp + 10 days);
        // Account accrues balance; if unlockTime is in the future, Collect's guard fails.
        vm.deal(_caller, deposit);
        vm.prank(_caller);
        c.Put{value: deposit}(unlockTime);

        // Move time forward so the unlockTime is strictly passed.
        vm.warp(block.timestamp + 11 days);

        // The amount must be within the collected holder's balance; the upper bound includes the whole balance
        // so that both partial and full withdrawals are explored.
        uint256 am = bound(_am, 0, deposit);

        // The Collect guard requires balance >= MinSum and balance >= am.
        // The recipient is the caller (an EOA with no code), so the low-level call succeeds.
        // Reference: balance decreases and Log records the withdrawal.
        // Mutant: the require on the call success flag is also satisfied, so behavior should match here.
        // The bug only manifests when the underlying call fails; use a failing callee below.

        // For an EOA recipient the call cannot fail; this branch is exercised for completeness,
        // and the property must hold identically for both reference and mutant.
        vm.prank(_caller);
        c.Collect(am);

        // General invariant over the public surface: after any admissible Put+Collect round,
        // the recorded Acc balance cannot exceed what was deposited, and if Collect succeeded
        // the remaining balance equals deposit - am.
        (uint256 recordedUnlockTime, uint256 recordedBalance) = c.Acc(_caller);
        recordedUnlockTime; // silence unused warning
        assertTrue(recordedBalance <= deposit);
    }
}
